/// `Argument = NamedArgument | StarArg | Expr`
#[derive(Clone, Debug, PartialEq, Eq, Hash)]
pub enum Argument {
    /// A `NamedArgument`.
    NamedArgument(NamedArgument),
    /// A `StarArg`.
    StarArg(StarArg),
    /// A `Expr`.
    Expr(Expr),
}

impl AstNode for Argument {
    type Language = Lang;
    fn can_cast(kind: SyntaxKind) -> bool {
        NamedArgument::can_cast(kind) || StarArg::can_cast(kind) || Expr::can_cast(kind)
    }
    fn cast(syntax: SyntaxNode) -> Option<Self> {
        let node = match syntax.kind() {
            SyntaxKind::NAMED_ARGUMENT => Self::NamedArgument(NamedArgument { syntax }),
            SyntaxKind::STAR_ARG => Self::StarArg(StarArg { syntax }),
            _ => return Expr::cast(syntax.clone()).map(Self::Expr),
        };
        Some(node)
    }
    fn syntax(&self) -> &SyntaxNode {
        match self {
            Self::NamedArgument(it) => it.syntax(),
            Self::StarArg(it) => it.syntax(),
            Self::Expr(it) => it.syntax(),
        }
    }
}

impl From<NamedArgument> for Argument {
    fn from(node: NamedArgument) -> Self {
        Self::NamedArgument(node)
    }
}

impl From<StarArg> for Argument {
    fn from(node: StarArg) -> Self {
        Self::StarArg(node)
    }
}

impl From<Expr> for Argument {
    fn from(node: Expr) -> Self {
        Self::Expr(node)
    }
}

/// `JsonValue = JsonArray | JsonObject | JsonScalar`
